(function(){"use strict";const CONFIG={storageKey:"autoApplyCoupon",discountCodeInputSelector:'#modal-discount-code, #discountCode, input[name="discount_code"]',bookingFormSelector:"#booking_form",successModalSelector:"#booking-success-modal"};function autoApplyCoupon(){try{if(window.__autoCouponAppliedOnce||document.querySelector('form[data-submitting="true"]')){return}let savedCoupon=localStorage.getItem(CONFIG.storageKey);if(!savedCoupon){savedCoupon=localStorage.getItem("spinningWheelWinningCoupon")}if(!savedCoupon){return}const selectors=CONFIG.discountCodeInputSelector.split(", ");let discountInput=null;for(const selector of selectors){discountInput=document.querySelector(selector);if(discountInput){break}}if(!discountInput){return}if(discountInput.value&&discountInput.value.trim().length>0){return}if(document.activeElement===discountInput){return}discountInput.value=savedCoupon;window.__autoCouponAppliedOnce=true;if(window.priceCalculator&&typeof window.priceCalculator.validateAndShowCoupon==="function"){window.priceCalculator.validateAndShowCoupon(savedCoupon)}else{setTimeout(()=>{discountInput.dispatchEvent(new Event("blur"))},100)}const changeEvent=new Event("change",{bubbles:true});discountInput.dispatchEvent(changeEvent);const inputEvent=new Event("input",{bubbles:true});discountInput.dispatchEvent(inputEvent)}catch(error){console.error("Error auto-applying coupon:",error)}}function removeCouponAfterBooking(){try{const savedCoupon=localStorage.getItem(CONFIG.storageKey);const spinningWheelCoupon=localStorage.getItem("spinningWheelWinningCoupon");if(!savedCoupon&&!spinningWheelCoupon){return}localStorage.removeItem(CONFIG.storageKey);localStorage.removeItem("spinningWheelWinningCoupon");localStorage.removeItem("spinningWheelRewardReceived");showCouponUsedNotification(savedCoupon||spinningWheelCoupon)}catch(error){console.error("Error removing coupon:",error)}}function getCurrentLanguage(){const storedLang=localStorage.getItem("lang")||localStorage.getItem("language")||localStorage.getItem("i18nextLng");if(storedLang){const lang=storedLang.split("-")[0];if(["en","ru","ro"].includes(lang)){return lang}}if(typeof i18next!=="undefined"&&i18next.language){const i18nextLang=i18next.language.split("-")[0];if(["en","ru","ro"].includes(i18nextLang)){return i18nextLang}}const htmlLang=document.documentElement.lang;if(htmlLang){const lang=htmlLang.split("-")[0];if(["en","ru","ro"].includes(lang)){return lang}}return"en"}function showCouponUsedNotification(couponCode){try{if(document.getElementById("coupon-used-notification")){return}const currentLang=getCurrentLanguage();const translations={en:{title:"Coupon Used!",message:"Thank you for your booking!"},ru:{title:"Купон Использован!",message:"Спасибо за бронирование!"},ro:{title:"Cupon Utilizat!",message:"Mulțumim pentru rezervare!"}};const t=translations[currentLang]||translations.en;const notification=document.createElement("div");notification.id="coupon-used-notification";notification.className="coupon-notification-container";const confettiColors=["#FFD700","#00CED1","#32CD32"];let confettiHTML="";for(let i=0;i<4;i++){const color=confettiColors[Math.floor(Math.random()*confettiColors.length)];const left=Math.random()*100;const delay=Math.random()*.3;const duration=1+Math.random()*.5;confettiHTML+=`<div class="confetti" style="\n          left: ${left}%;\n          background: ${color};\n          animation-delay: ${delay}s;\n          animation-duration: ${duration}s;\n        "></div>`}notification.innerHTML=`\n        <div class="confetti-container">${confettiHTML}</div>\n        <div class="coupon-notification-card" style="background: linear-gradient(135deg, #17a2b8 0%, #138496 100%);">\n          <div class="coupon-gift-icon">\n            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">\n              <polyline points="20 6 9 17 4 12"></polyline>\n            </svg>\n          </div>\n          <div class="coupon-notification-content">\n            <div class="coupon-title">\n              <span class="sparkle">✨</span>\n              ${t.title}\n              <span class="sparkle">✨</span>\n            </div>\n            <div class="coupon-code-container">\n              <span class="coupon-label">Code:</span>\n              <span class="coupon-code">${couponCode}</span>\n            </div>\n            <div class="coupon-message">\n              <span class="check-icon">✓</span>\n              ${t.message}\n            </div>\n          </div>\n          <div class="coupon-shine"></div>\n        </div>\n      `;document.body.appendChild(notification);setTimeout(()=>{if(notification.parentNode){notification.style.animation="slideInBounce 0.4s ease-out reverse";notification.style.opacity="0";setTimeout(()=>{if(notification.parentNode){notification.parentNode.removeChild(notification)}},400)}},5e3)}catch(error){console.error("Error showing coupon used notification:",error)}}function setupBookingSuccessListener(){document.addEventListener("bookingSuccess",function(event){removeCouponAfterBooking()});const observer=new MutationObserver(function(mutations){mutations.forEach(function(mutation){if(mutation.type==="childList"){mutation.addedNodes.forEach(function(node){if(node.nodeType===Node.ELEMENT_NODE){if(node.id==="booking-success-modal"||node.querySelector&&node.querySelector(CONFIG.successModalSelector)){removeCouponAfterBooking()}}})}})});observer.observe(document.body,{childList:true,subtree:true})}function init(){setupSpinningWheelListener();setupBookingSuccessListener();setupPriceCalculatorListener();if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",()=>{setTimeout(()=>{autoApplyCoupon()},500)})}else{setTimeout(()=>{autoApplyCoupon()},500)}}function setupSpinningWheelListener(){document.addEventListener("click",function(event){if(event.target&&(event.target.textContent==="TRIMITE"||event.target.textContent==="Submit"||event.target.textContent==="Trimite"||event.target.textContent==="Apply to Booking"||event.target.textContent==="Aplică la Rezervare"||event.target.closest("button")&&(event.target.closest("button").textContent.includes("TRIMITE")||event.target.closest("button").textContent.includes("Apply to Booking")||event.target.closest("button").textContent.includes("Aplică la Rezervare")))){const isSpinningWheelContinue=event.target.closest(".spinning-wheel-phone-step")||event.target.closest("#universalPhoneStep");if(!isSpinningWheelContinue){setTimeout(()=>{autoApplyCoupon()},500)}}});const checkForApplyModalCalculation=()=>{if(window.applyModalCalculation){const originalApplyModalCalculation=window.applyModalCalculation;window.applyModalCalculation=function(){const result=originalApplyModalCalculation.apply(this,arguments);setTimeout(()=>{autoApplyCoupon()},100);return result}}else{setTimeout(checkForApplyModalCalculation,100)}};checkForApplyModalCalculation()}function setupPriceCalculatorListener(){const observer=new MutationObserver(function(mutations){mutations.forEach(function(mutation){if(mutation.type==="childList"){mutation.addedNodes.forEach(function(node){if(node.nodeType===Node.ELEMENT_NODE){const priceCalculator=node.querySelector?node.querySelector("#price-calculator-content"):node.id==="price-calculator-content"?node:null;if(priceCalculator||node.classList&&node.classList.contains("price-calculator-content")){setTimeout(()=>{autoApplyCoupon()},200)}}})}if(mutation.type==="attributes"&&mutation.attributeName==="style"){const target=mutation.target;if(target.id==="price-calculator-content"||target.classList.contains("price-calculator-content")){const style=target.style.display;if(style==="block"||style==="flex"||!style){setTimeout(()=>{autoApplyCoupon()},200)}}}})});observer.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:["style","class"]})}init();window.AutoApplyCoupon={autoApply:autoApplyCoupon,removeAfterBooking:removeCouponAfterBooking}})();